    return { kind: "tool", ref: { ref: `${session.file}#${entry.id}`, quote } };
  }
  const span = /^(.+?)#L([1-9]\d*)(?:-L?([1-9]\d*))?$/.exec(ref);
  if (span) {
    const file = workspaceFile(cwd, span[1]);
